 21→  videoHash?: string; // Privacy hash for private Vimeo videos
 22→  title: string;
 23→  onClose: () => void;
 24→  isModal?: boolean; // If true, renders as modal overlay. If false, renders as embedded player
 25→}
 26→
 27→export function VideoPlayer({ videoId, videoHash, title, onClose, isModal = true }: VideoPlayerProps) {
 28→  const playerRef = useRef<HTMLDivElement>(null);
 29→  const vimeoPlayerRef = useRef<Player | null>(null);
 30→  const [initError, setInitError] = useState(false);
 31→
 32→  useEffect(() => {
 33→    if (!playerRef.current) return;
 34→
 35→    let isMounted = true;
 36→
 37→    // Always use URL format for consistent embed behavior across all videos
 38→    // URL format works better with Vimeo's embed domain restrictions
 39→    const videoUrl = videoHash
 40→      ? `https://vimeo.com/${videoId}/${videoHash}`
 41→      : `https://vimeo.com/${videoId}`;
 42→
 43→    const initPlayer = async () => {
 44→      try {
 45→        const VimeoPlayer = await loadVimeoPlayer();
 46→        if (!isMounted || !playerRef.current) return;
 47→
 48→        vimeoPlayerRef.current = new VimeoPlayer(playerRef.current!, {
 49→          url: videoUrl as `https://vimeo.com/${string}`,
 50→          width: 1280,
 51→          responsive: true,
 52→          autoplay: isModal, // Only autoplay in modal mode
 53→          color: '6a6a6a',
 54→          controls: true
 55→        });
 56→
 57→        // Race between ready() and timeout
 58→        const readyPromise = vimeoPlayerRef.current.ready();
 59→        const timeoutPromise = new Promise<never>((_, reject) => {
 60→          setTimeout(() => reject(new Error('VideoPlayer initialization timeout')), INIT_TIMEOUT_MS);
 61→        });
 62→
 63→        await Promise.race([readyPromise, timeoutPromise]);
 64→
 65→        if (!isMounted) {
 66→          vimeoPlayerRef.current?.destroy();
 67→          return;
 68→        }
 69→
 70→        // Add error event listener for runtime failures
 71→        vimeoPlayerRef.current.on('error', (error) => {
 72→          console.error('VideoPlayer: Player error', videoId, error);
 73→        });
 74→      } catch (err) {
 75→        console.error('VideoPlayer: Player init failed', videoId, err);
 76→        if (isMounted) {
 77→          setInitError(true);
 78→        }
 79→      }
 80→    };
 81→
 82→    initPlayer();
 83→
 84→    return () => {
 85→      isMounted = false;
 86→      vimeoPlayerRef.current?.destroy();
 87→    };
 88→  }, [videoId, videoHash, isModal]);
 89→
 90→  // Close on Escape key (only for modal)
 91→  useEffect(() => {
 92→    if (!isModal) return;
 93→
 94→    const handleEscape = (e: KeyboardEvent) => {
 95→      if (e.key === 'Escape') onClose();
 96→    };
 97→
 98→    window.addEventListener('keydown', handleEscape);
 99→    return () => window.removeEventListener('keydown', handleEscape);
100→  }, [onClose, isModal]);
101→
102→  // Error fallback component
103→  const ErrorFallback = () => (
104→    <div
105→      className="w-full flex items-center justify-center"
106→      style={{
107→        aspectRatio: '16/9',
108→        backgroundColor: 'var(--bg-card)',
109→        color: 'var(--text-muted)'
110→      }}
111→    >
112→      <span>Video unavailable</span>
113→    </div>
114→  );
115→
116→  // Embedded player (for project page)
117→  if (!isModal) {
118→    return (
119→      <div className="w-full">
120→        {initError ? (
121→          <ErrorFallback />
122→        ) : (
123→          <div
124→            ref={playerRef}
125→            className="w-full"
126→            style={{aspectRatio: '16/9'}}
127→          />
128→        )}
129→        {title && (
130→          <div className="mt-6">
131→            <h2 className="text-xl md:text-2xl font-light" style={{color: 'var(--text-muted)'}}>
132→              {title}
133→            </h2>
134→          </div>
135→        )}
136→      </div>
137→    );
138→  }
139→
140→  // Modal player (for grid overlay)
141→  return (
142→    <div
143→      className="fixed inset-0 z-50 flex items-center justify-center p-4 md:p-8"
144→      style={{backgroundColor: 'rgba(0, 0, 0, 0.9)'}}
145→      onClick={onClose}
146→    >
147→      <div
148→        className="relative w-full max-w-6xl"
149→        onClick={(e) => e.stopPropagation()}
150→      >
151→        <button
152→          onClick={onClose}
153→          className="absolute -top-12 right-0 text-white hover:opacity-70 transition-opacity text-sm"
154→          aria-label="Close video"
155→        >
156→          Close ×
157→        </button>
158→
159→        {initError ? (
160→          <ErrorFallback />
161→        ) : (
162→          <div
163→            ref={playerRef}
164→            className="w-full"
165→            style={{aspectRatio: '16/9'}}
166→          />
167→        )}
168→
169→        {title && (
170→          <div className="mt-6 text-white">
171→            <h2 className="text-xl md:text-2xl font-light" style={{color: 'var(--text-secondary)'}}>
172→              {title}
173→            </h2>
174→          </div>
175→        )}
176→      </div>
177→    </div>
178→  );
179→}
