  3→import { useRef, useState, useCallback, useEffect } from 'react';
  4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
  5→import { loadVimeoPlayer } from '@/lib/vimeo';
  6→import { useOptionalVideoThumbnailManager } from './VideoThumbnailManager';
  7→
  8→/**
  9→ * VIDEO THUMBNAIL - Robust Hover-to-Play System
 10→ *
 11→ * Consistency guarantees:
 12→ * 1. Deterministic initialization with timeout (12s max)
 13→ * 2. Retry mechanism if initialization fails
 14→ * 3. Abort pending operations on mouse leave
 15→ * 4. Clean state reset on failures
 16→ * 5. Single active video enforcement via manager
 17→ * 6. AbortController is source of truth for cancellation
 18→ * 7. Manager stops ALL other videos on activation
 19→ */
 20→
 21→// Detect if device supports hover (desktop) vs touch-only (mobile)
 22→function useIsTouchDevice() {
 23→  const [isTouchDevice, setIsTouchDevice] = useState(false);
 24→
 25→  useEffect(() => {
 26→    const mediaQuery = window.matchMedia('(hover: none) and (pointer: coarse)');
 27→    setIsTouchDevice(mediaQuery.matches);
 28→
 29→    const handler = (e: MediaQueryListEvent) => setIsTouchDevice(e.matches);
 30→    mediaQuery.addEventListener('change', handler);
 31→    return () => mediaQuery.removeEventListener('change', handler);
 32→  }, []);
 33→
 34→  return isTouchDevice;
 35→}
 36→
 37→interface VideoThumbnailProps {
 38→  videoId: string;
 39→  videoHash?: string;
 40→  aspectRatio: string;
 41→  startTime?: number;
 42→  isCinematic?: boolean;
 43→  thumbnail?: string;
 44→}
 45→
 46→// Timeout for player initialization (12 seconds - supports slow connections)
 47→const INIT_TIMEOUT_MS = 12000;
 48→
 49→export function VideoThumbnail({
 50→  videoId,
 51→  videoHash,
 52→  startTime,
 53→  isCinematic = false,
 54→  thumbnail
 55→}: VideoThumbnailProps) {
 56→  const containerRef = useRef<HTMLDivElement>(null);
 57→  const playerRef = useRef<Player | null>(null);
 58→  const [isHovering, setIsHovering] = useState(false);
 59→  const [videoVisible, setVideoVisible] = useState(false);
 60→
 61→  // State tracking refs
 62→  const isInitializingRef = useRef(false);
 63→  const isReadyRef = useRef(false);
 64→  const hoveringRef = useRef(false);
 65→  const initFailedRef = useRef(false);
 66→  const abortControllerRef = useRef<AbortController | null>(null);
 67→  const instanceId = useRef(`${videoId}-${Math.random().toString(36).slice(2)}`);
 68→
 69→  // Detect touch device - show full opacity on mobile (no hover)
 70→  const isTouchDevice = useIsTouchDevice();
 71→
 72→  // Get manager if available (works with or without provider)
 73→  const manager = useOptionalVideoThumbnailManager();
 74→
 75→  // Clean destroy of player instance
 76→  const destroyPlayer = useCallback(() => {
 77→    if (playerRef.current) {
 78→      try {
 79→        playerRef.current.destroy();
 80→      } catch {
 81→        // Player may already be destroyed
 82→      }
 83→      playerRef.current = null;
 84→    }
 85→    isReadyRef.current = false;
 86→    isInitializingRef.current = false;
 87→  }, []);
 88→
 89→  // Stop this video - reset to initial state
 90→  // Called by manager when another video becomes active
 91→  const stopVideo = useCallback(() => {
 92→    // Abort any pending operations FIRST (critical for race condition prevention)
 93→    if (abortControllerRef.current) {
 94→      abortControllerRef.current.abort();
 95→      abortControllerRef.current = null;
 96→    }
 97→
 98→    // Reset all state immediately
 99→    hoveringRef.current = false;
100→    setVideoVisible(false);
101→    setIsHovering(false);
102→
103→    // Try to pause player regardless of ready state
104→    // The player might be in an intermediate state during initialization
105→    if (playerRef.current) {
106→      try {
107→        playerRef.current.pause().catch(() => {});
108→        if (isReadyRef.current) {
109→          playerRef.current.setCurrentTime(startTime ?? 0).catch(() => {});
110→        }
111→      } catch {
112→        // Player in bad state - destroy and allow re-init
113→        destroyPlayer();
114→        initFailedRef.current = false; // Allow retry
115→      }
116→    }
117→  }, [startTime, destroyPlayer]);
118→
119→  // Register with manager on mount
120→  useEffect(() => {
121→    const id = instanceId.current;
122→    if (manager) {
123→      manager.registerVideo(id, stopVideo);
124→      return () => manager.unregisterVideo(id);
125→    }
126→  }, [manager, stopVideo]);
127→
128→  // Cleanup on unmount
129→  useEffect(() => {
130→    return () => {
131→      destroyPlayer();
132→    };
133→  }, [destroyPlayer]);
134→
135→  const initializePlayer = useCallback(async (signal: AbortSignal): Promise<boolean> => {
136→    // Already have a ready player
137→    if (playerRef.current && isReadyRef.current) return true;
138→
139→    // Currently initializing or container missing
140→    if (isInitializingRef.current || !containerRef.current) return false;
141→
142→    // Previous init failed - reset to allow retry
143→    if (initFailedRef.current) {
144→      destroyPlayer();
145→      initFailedRef.current = false;
146→    }
147→
148→    isInitializingRef.current = true;
149→
150→    const baseConfig = {
151→      muted: true,
152→      loop: true,
153→      autoplay: false,
154→      controls: false,
155→      background: true,
156→      responsive: true,
157→      title: false,
158→      byline: false,
159→      portrait: false,
160→      dnt: true,
161→      playsinline: true
162→    };
163→
164→    try {
165→      // Check if aborted before heavy work
166→      if (signal.aborted) {
167→        isInitializingRef.current = false;
168→        return false;
169→      }
170→
171→      // Construct URL with privacy hash and start time
172→      const baseUrl = videoHash
173→        ? `https://vimeo.com/${videoId}/${videoHash}`
174→        : `https://vimeo.com/${videoId}`;
175→      const urlWithTime = startTime ? `${baseUrl}#t=${startTime}s` : baseUrl;
176→
177→      const VimeoPlayer = await loadVimeoPlayer();
178→      if (signal.aborted || !containerRef.current) {
179→        isInitializingRef.current = false;
180→        return false;
181→      }
182→
183→      playerRef.current = new VimeoPlayer(containerRef.current, {
184→        url: urlWithTime as `https://vimeo.com/${string}`,
185→        ...baseConfig
186→      });
187→
188→      // Race between ready() and timeout
189→      const readyPromise = playerRef.current.ready();
190→      const timeoutPromise = new Promise<never>((_, reject) => {
191→        setTimeout(() => reject(new Error('Initialization timeout')), INIT_TIMEOUT_MS);
192→      });
193→
194→      await Promise.race([readyPromise, timeoutPromise]);
195→
196→      // Check if aborted during ready
197→      if (signal.aborted) {
198→        destroyPlayer();
199→        return false;
200→      }
201→
202→      isReadyRef.current = true;
203→      isInitializingRef.current = false;
204→
205→      // Add error event listener for runtime failures
206→      playerRef.current.on('error', (error) => {
207→        console.error('VideoThumbnail: Player error', videoId, error);
208→        // Don't destroy - thumbnail remains visible as fallback
209→      });
210→
211→      return true;
212→
213→    } catch (err) {
214→      console.error('VideoThumbnail: Player init failed', videoId, err);
215→      destroyPlayer();
216→      initFailedRef.current = true;
217→      return false;
218→    }
219→  }, [videoId, videoHash, startTime, destroyPlayer]);
220→
221→  const handleMouseEnter = useCallback(async () => {
222→    const id = instanceId.current;
223→    hoveringRef.current = true;
224→
225→    // Abort any previous pending operations
226→    if (abortControllerRef.current) {
227→      abortControllerRef.current.abort();
228→    }
229→    abortControllerRef.current = new AbortController();
230→    const signal = abortControllerRef.current.signal;
231→
232→    // Tell manager to stop any other active video
233→    if (manager) {
234→      manager.activateVideo(id);
235→    }
236→
237→    setIsHovering(true);
238→
239→    // Initialize and play
240→    const initialized = await initializePlayer(signal);
241→
242→    // Check if we should still play (hover state + abort signal are the source of truth)
243→    if (!hoveringRef.current || signal.aborted) return;
244→
245→    if (initialized && playerRef.current && isReadyRef.current) {
246→      try {
247→        // Final abort check before play
248→        if (signal.aborted) return;
249→
250→        await playerRef.current.play();
251→
252→        // Verify still hovering before showing video layer
253→        if (hoveringRef.current && !signal.aborted) {
254→          setVideoVisible(true);
255→        } else {
256→          // Lost hover during play - pause immediately
257→          playerRef.current.pause().catch(() => {});
258→        }
259→      } catch (err) {
260→        // Play failed - log but don't break, thumbnail is visible
261→        console.warn('VideoThumbnail: Play failed', videoId, err);
262→      }
263→    }
264→  }, [manager, initializePlayer, videoId]);
265→
266→  const handleMouseLeave = useCallback(() => {
267→    hoveringRef.current = false;
268→
269→    if (manager) {
270→      manager.deactivateVideo(instanceId.current);
271→    } else {
272→      stopVideo();
273→    }
274→  }, [manager, stopVideo]);
275→
276→  // Use custom thumbnail if provided, otherwise Vimeo vumbnail
277→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
278→
279→  // Mobile: Static thumbnail only (no video player, no autoplay)
280→  if (isTouchDevice) {
281→    return (
282→      <div
283→        className="relative w-full overflow-hidden"
284→        style={{
285→          aspectRatio: '16/9',
286→          borderRadius: '6px',
287→          boxShadow: 'none'
288→        }}
289→      >
290→        <div
291→          className="absolute inset-0 w-full h-full"
292→          style={{
293→            backgroundImage: `url(${thumbnailUrl})`,
294→            backgroundSize: 'cover',
295→            backgroundPosition: 'center',
296→            backgroundColor: '#141414'
297→          }}
298→        />
299→      </div>
300→    );
301→  }
302→
303→  // Desktop: Full hover-to-play video functionality
304→  return (
305→    <div
306→      className="relative w-full overflow-hidden"
307→      style={{
308→        aspectRatio: '16/9',
309→        borderRadius: '6px',
310→        boxShadow: 'none'
311→      }}
312→      onMouseEnter={handleMouseEnter}
313→      onMouseLeave={handleMouseLeave}
314→    >
315→      {/* Static thumbnail - always visible */}
316→      <div
317→        className="absolute inset-0 w-full h-full"
318→        style={{
319→          backgroundImage: `url(${thumbnailUrl})`,
320→          backgroundSize: 'cover',
321→          backgroundPosition: 'center',
322→          backgroundColor: '#141414',
323→          // Light table effect: visible but muted → bright reveal
324→          // Base state: 60% opacity, subtle desaturation - readable but clearly "inactive"
325→          opacity: isHovering ? 1.0 : 0.85,
326→          filter: isHovering ? 'saturate(1) brightness(1)' : 'saturate(0.85) brightness(0.95)',
327→          transition: 'opacity 0.5s cubic-bezier(0.25, 0.1, 0.25, 1), filter 0.5s cubic-bezier(0.25, 0.1, 0.25, 1)'
328→        }}
329→      />
330→
331→      {/* Video layer - fades in when playing */}
332→      <div
333→        className="absolute left-1/2 top-0 h-full transition-opacity duration-300"
334→        style={{
335→          aspectRatio: isCinematic ? '2.39/1' : '16/9',
336→          transform: 'translateX(-50%)',
337→          opacity: videoVisible ? 1 : 0,
338→          pointerEvents: 'none',
339→          borderRadius: '6px',
340→          overflow: 'hidden'
341→        }}
342→      >
343→        <div
344→          ref={containerRef}
345→          className="absolute"
346→          style={{ top: '-1px', left: '-1px', right: '-1px', bottom: '-1px' }}
347→        />
348→      </div>
349→    </div>
350→  );
351→}
